#[inline]
fn fill_row2_stage_0(
    matrix1: &mut SMatrix<f64, 60, 84>,
    row: usize,
    m0: &[Vec<f64>; 3],
    m1: &[Vec<f64>; 3],
    m2: &[Vec<f64>; 3],
) {
    matrix1[(row, 0)] = m2[2][0] * m1[1][0] * m0[0][0]
        - m2[2][0] * m1[0][0] * m0[1][0]
        - m2[1][0] * m1[2][0] * m0[0][0]
        + m2[1][0] * m1[0][0] * m0[2][0]
        + m2[0][0] * m1[2][0] * m0[1][0]
        - m2[0][0] * m1[1][0] * m0[2][0];
    matrix1[(row, 1)] = m2[2][1] * m1[1][0] * m0[0][0] - m2[2][1] * m1[0][0] * m0[1][0]
        + m2[2][0] * m1[1][1] * m0[0][0]
        + m2[2][0] * m1[1][0] * m0[0][1]
        - m2[2][0] * m1[0][1] * m0[1][0]
        - m2[2][0] * m1[0][0] * m0[1][1]
        - m2[1][1] * m1[2][0] * m0[0][0]
        + m2[1][1] * m1[0][0] * m0[2][0]
        - m2[1][0] * m1[2][1] * m0[0][0]
        - m2[1][0] * m1[2][0] * m0[0][1]
        + m2[1][0] * m1[0][1] * m0[2][0]
        + m2[1][0] * m1[0][0] * m0[2][1]
        + m2[0][1] * m1[2][0] * m0[1][0]
        - m2[0][1] * m1[1][0] * m0[2][0]
        + m2[0][0] * m1[2][1] * m0[1][0]
        + m2[0][0] * m1[2][0] * m0[1][1]
        - m2[0][0] * m1[1][1] * m0[2][0]
        - m2[0][0] * m1[1][0] * m0[2][1];
    matrix1[(row, 2)] = m2[2][2] * m1[1][0] * m0[0][0] - m2[2][2] * m1[0][0] * m0[1][0]
        + m2[2][1] * m1[1][1] * m0[0][0]
        + m2[2][1] * m1[1][0] * m0[0][1]
        - m2[2][1] * m1[0][1] * m0[1][0]
        - m2[2][1] * m1[0][0] * m0[1][1]
        + m2[2][0] * m1[1][2] * m0[0][0]
        + m2[2][0] * m1[1][1] * m0[0][1]
        + m2[2][0] * m1[1][0] * m0[0][2]
        - m2[2][0] * m1[0][2] * m0[1][0]
        - m2[2][0] * m1[0][1] * m0[1][1]
        - m2[2][0] * m1[0][0] * m0[1][2]
        - m2[1][2] * m1[2][0] * m0[0][0]
        + m2[1][2] * m1[0][0] * m0[2][0]
        - m2[1][1] * m1[2][1] * m0[0][0]
        - m2[1][1] * m1[2][0] * m0[0][1]
        + m2[1][1] * m1[0][1] * m0[2][0]
        + m2[1][1] * m1[0][0] * m0[2][1]
        - m2[1][0] * m1[2][2] * m0[0][0]
        - m2[1][0] * m1[2][1] * m0[0][1]
        - m2[1][0] * m1[2][0] * m0[0][2]
        + m2[1][0] * m1[0][2] * m0[2][0]
        + m2[1][0] * m1[0][1] * m0[2][1]
        + m2[1][0] * m1[0][0] * m0[2][2]
        + m2[0][2] * m1[2][0] * m0[1][0]
        - m2[0][2] * m1[1][0] * m0[2][0]
        + m2[0][1] * m1[2][1] * m0[1][0]
        + m2[0][1] * m1[2][0] * m0[1][1]
        - m2[0][1] * m1[1][1] * m0[2][0]
        - m2[0][1] * m1[1][0] * m0[2][1]
        + m2[0][0] * m1[2][2] * m0[1][0]
        + m2[0][0] * m1[2][1] * m0[1][1]
        + m2[0][0] * m1[2][0] * m0[1][2]
        - m2[0][0] * m1[1][2] * m0[2][0]
        - m2[0][0] * m1[1][1] * m0[2][1]
        - m2[0][0] * m1[1][0] * m0[2][2];
}

