#[must_use]
pub fn setup_action(
    l1: &[SVector<f64, 6>; 6],
    l2: &[SVector<f64, 6>; 6],
) -> Option<SMatrix<f64, 64, 64>> {
    let mut m: [[[Vec<f64>; 3]; 5]; 6] =
        std::array::from_fn(|_| std::array::from_fn(|_| std::array::from_fn(|_| Vec::new())));
    for prim in 0..6 {
        for sec in 0..6 {
            if prim != sec {
                let r = if sec > prim { sec - 1 } else { sec };
                let [c0, c1, c2] = &mut m[prim][r];
                fill_row1(&l1[prim], &l2[prim], &l1[sec], &l2[sec], c0, c1, c2);
            }
        }
    }
    let mut matrix1p = SMatrix::<f64, 60, 84>::zeros();
    let (mut deca, mut row0, mut row1, mut row2) = (0, 0, 1, 2);
    for row in 0..60 {
        fill_row2(
            &mut matrix1p,
            row,
            &m[deca][row0],
            &m[deca][row1],
            &m[deca][row2],
        );
        row2 += 1;
        if row2 > 4 {
            row1 += 1;
            row2 = row1 + 1;
            if row1 > 3 {
                row0 += 1;
                row1 = row0 + 1;
                row2 = row1 + 1;
                if row0 > 2 {
                    deca += 1;
                    row0 = 0;
                    row1 = 1;
                    row2 = 2;
                }
            }
        }
    }
    let b = matrix1p.fixed_view::<60, 15>(0, 0).into_owned();
    let bt = b.transpose();
    let matrix1 = (bt * b).try_inverse()? * bt * matrix1p;
    let mut matrix2 = DMatrix::<f64>::zeros(93, 157);
    fill_action_template_section_0(&matrix1, &mut matrix2);
    fill_action_template_section_1(&matrix1, &mut matrix2);
    fill_action_template_section_2(&matrix1, &mut matrix2);
    fill_action_template_section_3(&matrix1, &mut matrix2);

    let matrix3 = matrix2
        .view((0, 0), (93, 93))
        .into_owned()
        .lu()
        .solve(&matrix2.view((0, 93), (93, 64)).into_owned())?;
    Some(action_from_eliminated(&matrix3))
}

